const TEXTS_40 = new Map<string, string>([["k0000", ""], ["k0001", "x"], ["k0002", "value of k0002"], ["k0003", "value of k0003"], ["k0004", "value of k0004"], ["k0005", "value of k0005"], ["k0006", "value of k0006"], ["k0007", "value of k0007"], ["k0008", "value of k0008"], ["k0009", "value of k0009"], ["k0010", "value of k0010"], ["k0011", "value of k0011"], ["k0012", "value of k0012"], ["k0013", "value of k0013"], ["k0014", "value of k0014"], ["k0015", "value of k0015"], ["k0016", "value of k0016"], ["k0017", "value of k0017"], ["k0018", "value of k0018"], ["k0019", "value of k0019"], ["k0020", "value of k0020"], ["k0021", "value of k0021"], ["k0022", "value of k0022"], ["k0023", "value of k0023"], ["k0024", "value of k0024"], ["k0025", "value of k0025"], ["k0026", "value of k0026"], ["k0027", "value of k0027"], ["k0028", "value of k0028"], ["k0029", "value of k0029"], ["k0030", "value of k0030"], ["k0031", "value of k0031"], ["k0032", "value of k0032"], ["k0033", "value of k0033"], ["k0034", "value of k0034"], ["k0035", "value of k0035"], ["k0036", "value of k0036"], ["k0037", "value of k0037"], ["k0038", "value of k0038"], ["k0039", "value of k0039"]]);
const SHORT_KEYS = new Map<string, number>([["", 1], ["a", 2], ["ab", 3]]);

const KEY_COUNT = 3000;
const KEY_LENGTH = 5;
const STRIDE = KEY_LENGTH + 1;

const out: string[] = [];
function show(value: unknown): string {
  return typeof value === "string" ? JSON.stringify(value) : Object.is(value, -0) ? "-0" : String(value);
}
function say(label: string, ...parts: unknown[]) {
  out.push(label + ": " + parts.map(show).join(" "));
}
function checksum(sum: number, text: string): number {
  for (let i = 0; i < text.length; i++) sum = (Math.imul(sum, 31) + text.charCodeAt(i)) | 0;
  return sum;
}
function describeKeys(keys: Iterable<unknown>): string {
  const list = [...keys].map(show);
  let sum = 0;
  for (const key of list) sum = checksum(sum, key);
  return `${list.length} keys ${list.slice(0, 2).join()} .. ${list.slice(-2).join()} checksum ${sum}`;
}

const names: string[] = [];
for (let i = 0; i < KEY_COUNT; i++) names.push("k" + String(10000 + i).slice(1));
const narrowText = "|" + names.join("|") + "|";
const wideText = "Ж" + narrowText;
const nearMissText = "|" + names.map(text => text.slice(0, -1) + "x").join("|") + "|";
const wideNearMissText = "|" + names.map(text => text.slice(0, -1) + "Ж").join("|") + "|";

type CreateKey = (index: number) => string;
const start = (index: number) => 1 + index * STRIDE;
const end = (index: number) => start(index) + KEY_LENGTH;

const presentForms: [string, CreateKey][] = [
  ["slice", i => narrowText.slice(start(i), end(i))],
  ["slice counted from the end", i => narrowText.slice(start(i) - narrowText.length, end(i) - narrowText.length)],
  ["substring", i => narrowText.substring(end(i), start(i))],
  ["substr", i => narrowText.substr(start(i), KEY_LENGTH)],
  ["slice of a slice", i => narrowText.slice(start(i) - 1, end(i) + 1).slice(1, -1)],
  ["slice of 16-bit text", i => wideText.slice(start(i) + 1, end(i) + 1)],
  ["slice of a slice of 16-bit text", i => wideText.slice(start(i), end(i) + 2).slice(1, -1)],
  ["slice equal to the whole", i => names[i].slice(0)],
];
const absentForms: [string, CreateKey][] = [
  ["last character differs", i => nearMissText.slice(start(i), end(i))],
  ["last character is 16-bit", i => wideNearMissText.slice(start(i), end(i))],
  ["one character shorter", i => narrowText.slice(start(i), end(i) - 1)],
  ["one character longer", i => narrowText.slice(start(i), end(i) + 1)],
  ["empty slice", i => narrowText.slice(start(i), start(i))],
];
const sliceOfNarrowText = presentForms[0][1];
const sliceOfWideText = presentForms[5][1];
const wholeName: CreateKey = i => names[i];

let guard = 0;
function sliceKeys(text: string, first: number, count: number): string[] {
  if (guard > 1e9) sliceKeys(text + "x", first, count);
  const keys: string[] = [];
  for (let i = 0; i < count; i++) keys.push(text.slice(first + i * STRIDE, first + i * STRIDE + KEY_LENGTH));
  return keys;
}
function sumValues(map: Map<string, number>, keys: string[]): number {
  if (guard > 1e9) sumValues(map, keys);
  let sum = 0;
  for (let i = 0; i < keys.length; i++) sum += map.get(keys[i]) ?? -1;
  return sum;
}
function countMembers(set: Set<string>, keys: string[]): number {
  if (guard > 1e9) countMembers(set, keys);
  let count = 0;
  for (let i = 0; i < keys.length; i++) if (set.has(keys[i])) count++;
  return count;
}
function sumValuesOfSlices(map: Map<string, number>, text: string, first: number, count: number): number {
  let sum = 0;
  for (let i = 0; i < count; i++) sum += map.get(text.slice(first + i * STRIDE, first + i * STRIDE + KEY_LENGTH)) ?? -1;
  return sum;
}
function sliceKeysOfTemporaryText(from: number, to: number): string[] {
  return sliceKeys("#" + names.slice(from, to).join("#") + "#", 1, to - from);
}

function probeMap(map: Map<string, number>, limit: number, createKey: CreateKey): string {
  let found = 0, sum = 0, text = 0, mismatches = 0;
  for (let i = 0; i < limit; i++) {
    const first = createKey(i), second = createKey(i);
    const value = map.get(first);
    const isPresent = map.has(second);
    if (map.get(first) !== value || map.has(second) !== isPresent || map.get(second) !== value || map.has(first) !== isPresent) mismatches++;
    if (isPresent !== (value !== undefined) || first !== second) mismatches++;
    if (isPresent) {
      found++;
      sum += value!;
    }
    text = checksum(checksum(text, first), second);
  }
  return `map ${found} found, sum ${sum}, text ${text}, mismatches ${mismatches}`;
}
function probeSet(set: Set<string>, limit: number, createKey: CreateKey): string {
  let found = 0, text = 0, mismatches = 0;
  for (let i = 0; i < limit; i++) {
    const key = createKey(i);
    const isPresent = set.has(key);
    if (set.has(key) !== isPresent || set.has(createKey(i)) !== isPresent) mismatches++;
    if (isPresent) found++;
    text = checksum(text, key);
  }
  return `set ${found} found, text ${text}, mismatches ${mismatches}`;
}
function probeTexts(map: Map<string, string>, limit: number, createKey: CreateKey): string {
  let found = 0, text = 0, mismatches = 0;
  for (let i = 0; i < limit; i++) {
    const key = createKey(i);
    const value = map.get(key);
    if (map.get(key) !== value || map.get(createKey(i)) !== value || map.has(createKey(i)) !== (value !== undefined)) mismatches++;
    if (value !== undefined) {
      found++;
      text = checksum(text, value);
    }
  }
  return `${found} found, text ${text}, mismatches ${mismatches}`;
}

interface Tables {
  label: string;
  count: number;
  limit: number;
  map: Map<string, number>;
  set: Set<string>;
}
function buildTables(label: string, count: number, limit: number, createKey: CreateKey): Tables {
  const map = new Map<string, number>();
  const set = new Set<string>();
  for (let i = 0; i < count; i++) {
    map.set(createKey(i), i * 3);
    set.add(createKey(i));
  }
  return { label: label + " " + count, count, limit, map, set };
}
function addAndDeleteObjectKey(tables: Tables): Tables {
  const map = tables.map as Map<unknown, number>, set = tables.set as Set<unknown>;
  const key = {};
  map.set(key, 0);
  set.add(key);
  map.delete(key);
  set.delete(key);
  return tables;
}

const allTables: Tables[] = [
  { label: "constant 3", count: 3, limit: 30, map: NUMBERS_3, set: NAMES_3 },
  { label: "constant 40", count: 40, limit: 100, map: NUMBERS_40, set: NAMES_40 },
  { label: "constant 3000", count: 3000, limit: 3000, map: NUMBERS_3000, set: NAMES_3000 },
];
for (const [count, limit] of [[3, 30], [40, 100], [3000, 3000]]) {
  allTables.push(buildTables("built", count, limit, wholeName));
  allTables.push(buildTables("built from slices", count, limit, sliceOfNarrowText));
  allTables.push(addAndDeleteObjectKey(buildTables("built, then an object key", count, limit, wholeName)));
}

for (const { label, limit, map, set } of allTables) {
  for (const [form, createKey] of presentForms) say(label + ", " + form, probeMap(map, limit, createKey), probeSet(set, limit, createKey));
  for (const [form, createKey] of absentForms) say(label + ", " + form, probeMap(map, limit, createKey), probeSet(set, limit, createKey));
  const keys = sliceKeys(narrowText, 1, limit), wideKeys = sliceKeys(wideText, 2, limit), nearMissKeys = sliceKeys(nearMissText, 1, limit);
  say(label + ", each array of keys looked up twice", sumValues(map, keys), sumValues(map, keys), sumValues(map, wideKeys), sumValues(map, wideKeys), sumValues(map, nearMissKeys), sumValues(map, nearMissKeys));
  say(label + ", the same arrays in the set", countMembers(set, keys), countMembers(set, wideKeys), countMembers(set, nearMissKeys), countMembers(set, sliceKeys(narrowText, 1, limit)), countMembers(set, sliceKeys(wideText, 2, limit)));
  say(label + ", slices created in the loop", sumValuesOfSlices(map, narrowText, 1, limit), sumValuesOfSlices(map, wideText, 2, limit), sumValuesOfSlices(map, nearMissText, 1, limit));
  say(label + ", the keys afterwards", checksum(0, keys.join()), checksum(0, wideKeys.join()), checksum(0, nearMissKeys.join()), keys[1] === names[1], wideKeys[2] === names[2], nearMissKeys[0].length);
}
guard += out.length > 1e12 ? 1 : 0;

for (const [form, createKey] of presentForms) say("constant texts, " + form, probeTexts(TEXTS_40, 100, createKey));
for (const [form, createKey] of absentForms) say("constant texts, " + form, probeTexts(TEXTS_40, 100, createKey));
say("constant texts, values", TEXTS_40.get(sliceOfNarrowText(0)), TEXTS_40.get(sliceOfWideText(1)), TEXTS_40.get(sliceOfNarrowText(39)), TEXTS_40.get(sliceOfNarrowText(40)), TEXTS_40.get(sliceOfNarrowText(7)) === TEXTS_40.get(names[7]));

function changeTables({ label, count, limit, map, set }: Tables) {
  const step = count > 100 ? 7 : 1;
  let chained = 0;
  for (let i = 0; i < count; i += step) {
    const createKey = presentForms[i % presentForms.length][1];
    if (map.set(createKey(i), -i) === map) chained++;
    if (set.add(createKey(i)) === set) chained++;
  }
  say(label + ", present keys stored", map.size, set.size, chained, probeMap(map, limit, sliceOfNarrowText));
  for (let i = 0; i < count; i += step) {
    const createKey = absentForms[i % 2][1];
    map.set(createKey(i), i);
    map.set(createKey(i), i + 1);
    set.add(createKey(i));
    set.add(createKey(i));
  }
  say(label + ", absent keys stored", map.size, set.size, probeMap(map, limit, absentForms[0][1]), probeSet(set, limit, absentForms[1][1]));
  say(label + ", order", describeKeys(map.keys()), describeKeys(set));
  for (let i = 0; i < count; i += 2 * step) {
    map.delete(names[i]);
    set.delete(names[i]);
  }
  say(label + ", keys deleted", map.size, set.size, probeMap(map, limit, sliceOfNarrowText), probeSet(set, limit, sliceOfWideText));
  for (let i = 0; i < count; i += 2 * step) {
    map.set(sliceOfWideText(i), i);
    set.add(sliceOfWideText(i));
  }
  say(label + ", stored again from 16-bit text", map.size, set.size, probeMap(map, limit, sliceOfNarrowText), probeSet(set, limit, sliceOfNarrowText), probeMap(map, limit, sliceOfWideText), probeSet(set, limit, sliceOfWideText));
  say(label + ", order afterwards", describeKeys(map.keys()), describeKeys(set));
  map.clear();
  set.clear();
  say(label + ", cleared", map.get(sliceOfNarrowText(0)), map.has(sliceOfWideText(1)), set.has(sliceOfNarrowText(2)));
  map.set(sliceOfNarrowText(1), 1);
  set.add(sliceOfWideText(1));
  say(label + ", filled again", map.get(sliceOfWideText(1)), map.get(sliceOfNarrowText(2)), set.has(sliceOfNarrowText(1)), set.has(sliceOfNarrowText(2)));
}
for (const tables of allTables) changeTables(tables);

for (const [label, prefix] of [["Latin-1", "é"], ["16-bit", "ж"]]) {
  const prefixed = "|" + names.slice(0, 100).map(text => prefix + text).join("|") + "|";
  const widened = "Ж" + prefixed;
  const slicePrefixed = (text: string, first: number): CreateKey => i => text.slice(first + i * (STRIDE + 1), first + i * (STRIDE + 1) + KEY_LENGTH + 1);
  const { map } = buildTables(label, 40, 100, slicePrefixed(prefixed, 1));
  const { set } = buildTables(label, 40, 100, slicePrefixed(widened, 2));
  say(label + " keys", probeMap(map, 100, slicePrefixed(prefixed, 1)), probeMap(map, 100, slicePrefixed(widened, 2)), probeSet(set, 100, slicePrefixed(prefixed, 1)), probeSet(set, 100, slicePrefixed(widened, 2)));
  say(label + " keys without the prefix", probeMap(map, 100, slicePrefixed(prefixed, 2)), probeSet(set, 100, sliceOfNarrowText));
}

{
  const letters = ["x", "a", "b", "x"].join("");
  const built = new Map<string, number>().set("", 1).set("a", 2).set("ab", 3);
  for (const [label, map] of [["constant", SHORT_KEYS], ["built", built]] as [string, Map<string, number>][]) {
    say(label + " short keys", map.get(letters.slice(1, 1)), map.get(letters.slice(1, 2)), map.get(letters.slice(1, 3)), map.get(letters.slice(1, 4)), map.get(letters.slice(0, 2)), map.has(letters.slice(4)), map.has(letters.slice(2, 4)));
  }
  const emptyMap = new Map<string, number>(), emptySet = new Set<string>();
  say("empty tables", emptyMap.get(sliceOfNarrowText(0)), emptyMap.has(sliceOfWideText(0)), emptySet.has(sliceOfNarrowText(0)), emptyMap.get(letters.slice(1, 1)));
}

{
  const { map, set } = buildTables("collected", 50, 100, wholeName);
  const present = sliceKeysOfTemporaryText(0, 50), absent = sliceKeysOfTemporaryText(50, 100);
  const before = [sumValues(map, present), countMembers(set, present), sumValues(map, absent), countMembers(set, absent)];
  Bun.gc(true);
  const garbage: string[] = [];
  for (let i = 0; i < 20000; i++) garbage.push(narrowText.slice(i % 1000, (i % 1000) + 9));
  Bun.gc(true);
  say("after collections", before.join(), sumValues(map, present), countMembers(set, present), sumValues(map, absent), countMembers(set, absent), checksum(0, present.join()), checksum(0, absent.join()), garbage.length);
}

for (const hadObjectKey of [false, true]) {
  const tables = buildTables("stored through Map<unknown, number>", 40, 100, wholeName);
  if (hadObjectKey) addAndDeleteObjectKey(tables);
  const map = tables.map as Map<unknown, number>, set = tables.set as Set<unknown>;
  for (let i = 30; i < 50; i++) {
    map.set(sliceOfNarrowText(i), 7000 + i);
    set.add(sliceOfWideText(i));
  }
  say(tables.label + (hadObjectKey ? ", after an object key" : ""), map.size, set.size, map.get(sliceOfWideText(35)), map.get(sliceOfNarrowText(45)), map.has(sliceOfNarrowText(50)), set.has(sliceOfNarrowText(49)), set.has(sliceOfNarrowText(50)), describeKeys(map.keys()), describeKeys(set));
}

{
  const { map, set } = buildTables("mixed", 40, 100, wholeName);
  const anyMap = map as Map<unknown, number>, anySet = set as Set<unknown>;
  const texts = ["<12", "NaN", "0", "-0", "k0001", "[object Object]>"].join("|");
  const twelve = () => texts.slice(1, 3), notANumber = () => texts.slice(4, 7), zero = () => texts.slice(8, 9), negativeZero = () => texts.slice(10, 12);
  const object = { toString: () => "k0001" };
  anyMap.set(12, 1000).set(object, 1001).set(NaN, 1002).set(-0, 1003);
  anySet.add(12).add(object).add(NaN).add(-0);
  say("other keys beside strings", map.size, set.size, probeMap(map, 100, sliceOfNarrowText), probeSet(set, 100, sliceOfWideText));
  say("texts of the other keys", map.get(twelve()), map.get(notANumber()), map.get(zero()), map.get(negativeZero()), map.get(texts.slice(19, 34)), set.has(twelve()), set.has(notANumber()), set.has(zero()), set.has(negativeZero()));
  say("the other keys", anyMap.get(12), anyMap.get(object), anyMap.get({}), anyMap.get(NaN), anyMap.get(0), anyMap.get(-0), anyMap.get(12.5), anySet.has(12), anySet.has(object), anySet.has(NaN), anySet.has(0), anySet.has(-0));
  map.set(twelve(), 2000).set(notANumber(), 2002).set(zero(), 2003).set(negativeZero(), 2004);
  set.add(twelve()).add(notANumber()).add(zero()).add(negativeZero());
  say("both kinds", map.size, set.size, map.get(twelve()), anyMap.get(12), map.get(notANumber()), anyMap.get(NaN), map.get(zero()), map.get(negativeZero()), anyMap.get(0), anyMap.get(-0), map.get(texts.slice(13, 18)), anyMap.get(object));
  say("both kinds in order", describeKeys(anyMap.keys()), describeKeys(anySet));
}

